-- Reviewed question-bank expansion. Preserve questions already managed by admins.
insert into public.topics(slug,title,subject) values
 ('athens-acropolis', 'Acropolis of Athens', 'Arts & culture'),
 ('borobudur', 'Borobudur Temple', 'Arts & culture'),
 ('statue-of-liberty', 'Statue of Liberty', 'History'),
 ('rosetta-philae', 'Rosetta and Philae', 'Technology & inventions'),
 ('voyager-2', 'Voyager 2', 'Technology & inventions'),
 ('seismic-waves', 'Seismic waves', 'Science'),
 ('thunder', 'Thunder', 'Science'),
 ('lunar-eclipse', 'Lunar eclipses', 'Science'),
 ('gemini-x', 'Gemini X', 'History'),
 ('gemini-xii', 'Gemini XII', 'History'),
 ('neptune', 'Neptune', 'Science')
on conflict(slug) do nothing;

with expansion(slug,kind,prompt,presentation,solution,explanation,source_title,source_url) as (values
 ('athens-acropolis', 'where', 'Find the Acropolis that overlooks Greece’s capital.',
  '{}'::jsonb,
