  '{"min":1886,"max":1886,"precision":"year","scale":12,"label":"1886 CE"}'::jsonb,
  'The dedication took place on October 28, 1886, after the statue was shipped from France and reassembled in New York Harbor.', 'National Park Service: Statue of Liberty facts', 'https://www.nps.gov/stli/learn/statue-of-liberty-facts.htm'),
 ('rosetta-philae', 'when', 'In what year did Philae touch down on comet 67P?',
