  '{"min":2014,"max":2014,"precision":"year","scale":12,"label":"2014 CE"}'::jsonb,
  'Philae separated from the Rosetta spacecraft and touched down on November 12, 2014.', 'ESA: Rosetta timeline', 'https://education.esa.int/rosetta_timeline/'),
