  '{"correct":"portrait-2","label":"Michael Collins","credits":[{"id":"portrait-0","subject":"Neil Armstrong","image":"/media/4f0bd2.jpg","license":"Public domain (NASA)","artist":"NASA","medium":"photograph","url":"https://images.nasa.gov/details/S69-31741"},{"id":"portrait-1","subject":"Buzz Aldrin","image":"/media/8c81ee.jpg","license":"Public domain (NASA)","artist":"NASA","medium":"photograph","url":"https://images.nasa.gov/details/S69-31743"},{"id":"portrait-2","subject":"Michael Collins","image":"/media/0ab599.jpg","license":"Public domain (NASA)","artist":"NASA","medium":"photograph","url":"https://images.nasa.gov/details/S69-31742"},{"id":"portrait-3","subject":"Jim Lovell","image":"/media/bdc394.jpg","license":"Public domain (NASA)","artist":"NASA","medium":"photograph","url":"https://www.nasa.gov/former-astronaut-james-a-lovell/"}]}'::jsonb,
  'Michael Collins flew with John Young on Gemini X in July 1966.', 'NASA: Michael Collins biography', 'https://www.nasa.gov/former-astronaut-michael-collins/'),
