  'Buzz Aldrin was the pilot for Gemini XII, the final crewed Gemini mission.', 'NASA: Gemini XII', 'https://www.nasa.gov/mission/gemini-xii/'),
 ('neptune', 'what', 'Which planet is shown in this Voyager 2 image?',
  '{"options":[{"id":"option-1","label":"Neptune"},{"id":"option-2","label":"Uranus"},{"id":"option-3","label":"Jupiter"},{"id":"option-4","label":"Saturn"}],"images":["/media/6b4e2c.jpg","/media/94ca81.jpg","/media/cc73bf.jpg","/media/2f81ad.jpg"]}'::jsonb,
