insert into public.questions(topic_id,kind,prompt,presentation,solution,explanation,source_title,source_url,status,verified_at)
select t.id,e.kind,e.prompt,e.presentation,e.solution,e.explanation,e.source_title,e.source_url,'published','2026-11-24T00:00:00Z'::timestamptz
from expansion e join public.topics t on t.slug=e.slug
where not exists (select 1 from public.questions existing where existing.topic_id=t.id and existing.kind=e.kind)
on conflict do nothing;
